// Hand-derived minimal type surface of @cancjs/promise for type-aware rule fixtures.
// Not the real implementation; shapes only, kept in sync manually with the monorepo dist types.

export interface ICancelablePromiseFlagOptions {
 asyncCancel?: boolean;
 forceCancelable?: boolean;
 bubble?: boolean;
 strict?: boolean;
 shield?: boolean;
}

export interface ICancelablePromiseOptions extends ICancelablePromiseFlagOptions {
 signal?: AbortSignal | AbortSignal[];
}

export interface ICancelable<T = any> extends PromiseLike<T> {
 cancel(reason?: any): any;
}

export type TOnCancel = (reason?: any) => void;

export type TCancelablePromiseExecutor<T> = (
 resolve: (value?: T | PromiseLike<T>) => void,
 reject: (reason?: any) => void,
 handleCancel: (onCancel: TOnCancel) => void,
) => void;

export interface IHandleCancelOptions {
 immediate?: boolean;
}

export declare class CancelablePromise<T> implements ICancelable<T>, Promise<T> {
 static all<T>(
 values: Iterable<T | PromiseLike<T>>,
 options?: ICancelablePromiseOptions,
 ): CancelablePromise<T[]>;
 static allSettled<T>(
 values: Iterable<T>,
 options?: ICancelablePromiseOptions,
 ): CancelablePromise<PromiseSettledResult<Awaited<T>>[]>;
 static any<T>(
 values: Iterable<T | PromiseLike<T>>,
 options?: ICancelablePromiseOptions,
 ): CancelablePromise<Awaited<T>>;
 static race<T>(
 values: Iterable<T | PromiseLike<T>>,
 options?: ICancelablePromiseOptions,
 ): CancelablePromise<Awaited<T>>;
 static reject<T = never>(reason?: any, options?: ICancelablePromiseOptions): CancelablePromise<T>;
 static resolve(): CancelablePromise<void>;
 static resolve<T>(
 value: T | PromiseLike<T>,
 options?: ICancelablePromiseOptions,
 ): CancelablePromise<T>;
 static try<T, TArgs extends any[]>(
 fn: (...args: TArgs) => T | PromiseLike<T>,
 ...args: TArgs
 ): CancelablePromise<T>;

 readonly [Symbol.toStringTag]: string;

 constructor(executor: TCancelablePromiseExecutor<T>, options?: ICancelablePromiseOptions);

 get canceled(): boolean;
 get cancelable(): boolean;

 then<TResult1 = T, TResult2 = never>(
 onFulfilled?: ((value: T) => TResult1 | PromiseLike<TResult1>) | null,
 onRejected?: ((reason: any) => TResult2 | PromiseLike<TResult2>) | null,
 ): CancelablePromise<TResult1 | TResult2>;
 catch<TResult = never>(
 onRejected?: ((reason: any) => TResult | PromiseLike<TResult>) | null,
 ): CancelablePromise<T | TResult>;
 finally(onFinally?: (() => void) | null): CancelablePromise<T>;
 handleCancel(onCancel: TOnCancel, options?: IHandleCancelOptions): CancelablePromise<T>;
 cancel(reason?: any): void | CancelablePromise<PromiseSettledResult<unknown>[]>;
}

export interface ICancelErrorOptions {
 cause?: any;
}

export declare class CancelError extends Error {
 name: string;
 bubbled: boolean;
 disposed: boolean;
 cause?: any;
 constructor(reason?: string, options?: ICancelErrorOptions);
 get aborted(): boolean;
}

export declare const isCancelError: (error: any) => error is CancelError;
export declare const isCancPromise: (value: any) => value is CancelablePromise<any>;
export declare const isAbortError: (error: any) => boolean;
export declare function createAbortSignal(reason?: any): { abort: (r?: any) => void; signal: AbortSignal };
export declare function catchCancel<TResult>(
 promise: PromiseLike<TResult>,
): CancelablePromise<TResult | CancelError>;
export declare function suppressCancel<TResult>(
 promise: PromiseLike<TResult>,
): CancelablePromise<TResult | void>;
export declare function makeCancelable<T>(
 promise: PromiseLike<T>,
 options?: ICancelablePromiseOptions,
): CancelablePromise<T>;

export default CancelablePromise;
